cat /app/trial/agent/trajectory.json | python3 -c "
import json,sys
d=json.load(sys.stdin)
for i,s in enumerate(d['steps']):
    print('=== STEP', i, s.get('timestamp'), s.get('source'), '===')
    msg = s.get('message')
    if isinstance(msg, str):
        print(msg[:1500])
    else:
        print(json.dumps(msg)[:1500])
    tc = s.get('tool_calls')
    if tc:
        for t in tc:
            print('  TOOL:', json.dumps(t)[:800])
    obs = s.get('observation')
    if obs:
        print('  OBS:', json.dumps(obs)[:800])
    print()
"

